# （Excel 打开会自己重算，肉眼看不出来）。旧版是美化那一步才丢，现在 build 这一步就丢 ——
# 属于 build_report.py 头注里记的第 4 条有意差异。所以比对时把它们单列出来，不算"被改坏"。
#
# ⚠️ 2026-10-26：原先这里还有两条断言（"缓存值丢了" == 这四格、"公式仍是公式"），
