# 一个分类都没有时 10 格**全写空串**（用户口径「一个都没有为空」—— 数量列也不写 0，
# 见 stats/cells/_baseline.js 的 CATEGORY_MISSING）。
# ⚠️ 与 EXPECTED_EVENT_CELLS（那 21 格）**分开列**，虽然读的是同一份事件表：
# 两块的列不同（「安全事件二级分类」vs「GPT定性标签」）、槽位数不同（5 vs 7），
# 混在一组里，"这次是哪一列对不上"就分不出来了。
# 凡是要清点「哪些格子因为事件表缺列而报错」的地方，两组都要带上。
EXPECTED_EVENT_CATEGORY_LABEL_ROW = 51
EXPECTED_EVENT_CATEGORY_SLOTS = 5
EXPECTED_EVENT_CATEGORY_CELLS = [
    f'{column}{row}'
    for row in range(EXPECTED_EVENT_CATEGORY_LABEL_ROW,
                     EXPECTED_EVENT_CATEGORY_LABEL_ROW + EXPECTED_EVENT_CATEGORY_SLOTS)
    for column in ('C', 'D')
]
