# 与 EXPECTED_WEAKPWD_CELLS（D11）**分开列**，虽然读的是同一份弱密码表：
# D11 认的是「风险资产」+ 资产表圈定的核心 IP 集合 + 事件表「安全事件二级分类」的关键词，
# D16 认的是弱密码表的「处置状态」+ 同一张事件表的「安全事件二级分类」**且**「处置状态」。
# 缺列时两边报的是不同的列（D11 报缺「重要级别」/「影响资产」，D16 报缺「处置状态」），
# 混在一组里两类错误就分不开了。
# 但它该到的场合一个都不能少：凡是要清点「这次跑了哪些格」的地方，一律带上
# EXPECTED_DISPOSED_WEAKPWD_CELLS。
EXPECTED_DISPOSED_WEAKPWD_CELLS = ['D16']

# G8「处置安全事件总数」：只读事件表的「处置状态」一列，与 --business-systems 无关。
#
# 与 EXPECTED_EVENT_CELLS（那 21 格名次统计）**分开列**，虽然读的是同一份事件表：
# 那 21 格认的是「GPT定性标签」、缺列时写空串，G8 认的是「处置状态」、缺列时不写值 +
# 报错。两张列、两种后果，混在一组里两类错误就分不开了。
# 但它该到的场合一个都不能少：凡是要清点「这次跑了哪些格」的地方，一律带上
# EXPECTED_EVENT_SOURCE_CELLS（= 21 格 + G8），否则 G8 会变成一处"没人数的落值格"。
EXPECTED_EVENT_DISPOSITION_CELLS = ['G8']

# 事件表这一份数据源上所有**自己读表**的格子：21 格名次统计 + G8。
# 不含 D11 —— 它也读事件表，但还要资产表与弱密码表，缺表时的后果与这两组都不一样。
EXPECTED_EVENT_SOURCE_CELLS = EXPECTED_EVENT_CELLS + EXPECTED_EVENT_DISPOSITION_CELLS

# G7「威胁平均遏制时间」：也读事件表，但它**不是计数格** —— 全表唯一一个落小数均值的格子，
# 所以单独成组，不进上面那一组：
#   · 读的列不一样：G5 认「GPT研判结论」是在**告警表**上，G7 是同一句判据落在**事件表**上，
#     外加两个时间列（「事件遏制时间」「专家研判时间」）—— 后两列平台近版才有；
#   · 空表 / 无命中 / 命中行都算不出时长 -> 写 **0**（用户口径 2026-10-14「写 0，如果 G7
#     没写 0，也改过来」）。⚠️ 本组从前写**空串**、论据是"0 分钟是一个真实可能的均值，
#     会和没有可平均的样本混成一个数"——用户明确接受这个取舍，所以改 0；
#     G7 因此**已从 blank_rank_cells 挪进 empty_count_cells**；
#   · 缺列 -> 不写值 + 报错（缺「GPT研判结论」或两个时间列里的任何一个）。
# 它该到的场合一个都不能少：凡是要清点「这次跑了哪些格」的地方，一律带上
# EXPECTED_CONTAINED_CELLS（【1】【3】【4】那份不带总表的 ctx 上它也写 0）。
EXPECTED_CONTAINED_CELLS = ['G7']

# G9「事件平均响应时长」：读的也是事件表（与 G8 同一批「已处置」行 + 「推送状态」=「已推送」），
# 但它**不是计数格**，所以与 G8 分开、也与 G7 分开：
#   · 选行是 G8 那一批（复用 disposedEventRows），再加一道「推送状态」—— 判据是"同时满足"；
#   · 时长列「响应时长」与 G7 的「遏制时长」同源同性质（都由表格预处理在下载之后、解析之前
#     追加到事件表下载件上），所以两格的**缺列后果一样**；没样本时的落法**从前不一样**
#     （G7 写空串、G9 写 0），但 G7 已于**用户口径 2026-10-14** 改成写 0 —— 现在两格一致。
#   · 缺列 -> 不写值 + 报错（缺「处置状态」或「推送状态」或「响应时长」里的任何一个，
#     报的是第一个缺的：处置状态 -> 推送状态 -> 响应时长）。
#     ⇒ G9 仍进 empty_count_cells 那一组（空表下写 0），与 G7 现在**同组**；
#     blank_rank_cells 那一组从此只剩名次格，不再有时长均值格。
EXPECTED_RESPONSE_CELLS = ['G9']

# C58:N59「按月平均响应时长」那 24 格（用户口径 2026-10-14）—— 58 行月份标签、
# 59 行对应均值，逐列一一对应（C58 与 C59 是同一个槽位）。
#
# 单独成组，理由与 G7/G9 那两组同款：它读的也是**预处理追加的列**，但它多读一列、
# 而且是**唯一一组「一格一格按位置取」的格子**（同一份月份序列上取第 N 个），
# 既不是计数格也不是名次格：
#   · 读两列：预处理追加的「事件创建月份」（桶键）+「响应时长」（均值那一列）；
#   · 槽位超出报告期的月份数 -> 标签与值**都写空串**（报告期不足 12 个月时多出来的那几格）；
#     桶内没有样本 -> 写 **0**（用户口径 2026-10-14「写 0」，与 G7/G9/D35/D36/E49/G51:G55 同一条）；
#   · 缺列（有行、却读不出那两列里的任何一列）-> 不写值 + 报错。
# ⚠️ **哪一组都不进**，那 24 格的落值是**一格一格按槽位算的**：
#   · `empty_count_cells` 要求"这一组的格子全是 0" —— 成立，因为 `''` 不等于 0；
#   · `blank_rank_cells` 要求"全是空串" —— 也不成立，同理。
# 而**同一份 fixture 上这两种值同时出现**（报告期只有 1 个月时：C58 是那个月份、C59 是那个月的 0，
# D58:N58 与 D59:N59 是越界空串）—— 于是它既不能进"全 0"那组、也不能进"全空串"那组。
# 单独一段（【27】）逐格钉住这 24 个值，比塞进任何一组都更严：那一组的判据只是"全等于某个常量"。
# 越界空串与「名次格写空串」也不是一回事：那一组是"名次不够"（数据没那么多名次），
# 这一组是"槽位越界"（报告期不够长）—— 值同为 `''`，来历完全不同，所以不并组。
MONTH_LABEL_ROW = 58
MONTH_MEAN_ROW = 59
MONTH_SLOTS = 12
# 逐格字面列（**字符串序**，与 EXPECTED_FILE_CHANGES 同一条排法：'C58' < 'C59' < 'D58'）
