# D10 / D12 / D15 / D17。**凡是要清点「这次跑了哪些格」的地方都用这一组**。
EXPECTED_VULN_GROUP = EXPECTED_VULN_CELLS

# 「`--business-systems` 没给到那个槽位」时仍然**写 0** 的那几格（用户口径 2026-10-12）：
