#
# 单独成组，与资产表的另外两把钥匙（D3:D9 的「所属业务」-> IP 子串包含、D11 的
# 「重要级别」= 核心）分开：三处读同一张表、却认三样东西，缺列时后果也不同 ——
# 本格**不读「IP地址」**，所以资产表缺 IP 列时它照常落值，另两把钥匙不写值。
