#     （网络「内→外 且已拦截」、终端「已拦截」），两张表相加。所以它是
#     ctx.interceptedOutboundCount（stats/context.js 的 SCALAR_SOURCE_FIELDS）。
#     ⚠️ 与 G99 是**两个各自独立的 ctx 字段**：一个断不该牵连另一个 ——
#     验收里专门有一段"同一份输入下 G99 落值、D23 写「接口不通无值」"。
#   · D24 —— **读告警表一列**（「访问方向」），整格精确等于「内➝外」的行数
#     （stats/metrics/alarm.js 的 outboundAlarmCount）。数的是**告警行数**，
#     与 D23 的**日志条数**是两个不同的量、两套不同的数据源 ——
#     别把两者当成"同一个东西的两种算法"（验收里那两格刻意取不同的值）。
#   · D21 —— **不读盘、不调接口**：值 = D23 + D24，两个加数各走各的具名口径（H4）。
#     ⚠️ 它不是 alias（H5 只适用于"一个值写到多个地址"，这里是加法）。
#
# ⚠️ 三格**一起点名**的理由与 EXPECTED_DEVICE_CELLS 那种"共用一份实现只能一起点"
# 不完全相同 —— 这里是因为**它们互相之间的分界才是这一段的内容**：改 D21 的加法、
# 把 D23 接成 G99 的别名、让 D24 跟着 D23 一起断，任何一种都会在这里红。
# 所以凡是要清点「这次跑了哪些格」的地方，一律带上 EXPECTED_OUTBOUND_CELLS。
#
# ⚠️ 验收里 D23/D21 大多落 0、D24 落 0：那几段的 ctx 是手搭的
# （verify_write_layer.js 的 CTX_ARGS），没有 D23 那个标量字段（归一成 0 = 接口答了 0），
# 告警表要么没接、要么是空表（D24 = 0）。真的喂法与边界在【28】那一段。
EXPECTED_OUTBOUND_CELLS = ['D21', 'D23', 'D24']

# D27「重要时期安全日志数」/ D28「重要时期告警数」/ D29「重要时期事件数」
# —— 三格是同一套口径（用户口径 2026-10-14：「重要时期 = 报告期 ∩ 中国法定节假日
# **放假整段**」，定义见 stats/periods.js 的 importantPeriods、数据 stats/holidays.js），
# 但**数据来源三种各不相同**，正是这一段要钉的分界：
#
#   · D27 —— **接口类标量**，且与 G99/D23 是**同一个日志量端点上的第三次问**：
#     不筛（与 G99 同一种问法），但报告期被切成**重要时期段**，逐段各问一次、各段相加。
#     所以它是 ctx.importantPeriodLogCount（stats/context.js 的 SCALAR_SOURCE_FIELDS）。
#     ⚠️ **任一段不通 -> 整格「接口不通无值」**，不写"已通的那几段之和"
#     （后者会把"少算了几段"伪装成"算完了"，同 D21 对 D23 的加法穿透口径）。
#   · D28 —— **读告警表一列**（「最早发生时间」，**文本**形态），落在任一重要时期内的行数。
#   · D29 —— **读事件表一列**（「事件创建时间」，真 datetime -> **epoch 秒**），同上。
#     ⚠️ 这两格判据列的**单元格形态不同**（一个文本、一个 epoch 秒），却必须走
#     stats/metrics/rows.js 的 cellDateOnly **同一份归一** —— 只认一种形态的实现在这里红。
#
# ⚠️ 三格**一起点名**的理由与 EXPECTED_OUTBOUND_CELLS 相同：它们互相之间的分界才是这一段
# 的内容。所以凡是要清点「这次跑了哪些格」的地方，一律带上 EXPECTED_IMPORTANT_PERIOD_CELLS。
#
# ⚠️ 验收里这三格**大多落 0**：那几段的 ctx 是手搭的（verify_write_layer.js 的 CTX_ARGS，
# 报告期 2026-05-12 ~ 2026-05-13 —— **一个节假日都不含**），D27 那个标量字段没给
# （归一成 0 = 报告期内没有重要时期，那是结论）、两张表要么没接、要么是空表。
# 真的喂法与边界在【29】那一段。
EXPECTED_IMPORTANT_PERIOD_CELLS = ['D27', 'D28', 'D29']

# D90「重要时期值守次数」/ D91「重要时期安全事件数」（用户口径 2026-10-26）：
#   · D90 —— 报告期命中的节假日**条目数**（不是一个一个数天数）。数据源就是
