OUTBOUND_ALARM_DIRECTION = '访问方向'
OUTBOUND_DIRECTION_OUT = '内➝外'        # U+279D：表里实际写的那个值
OUTBOUND_DIRECTION_IN = '外➝内'
OUTBOUND_DIRECTION_INNER = '内➝内'
OUTBOUND_DIRECTION_NONE = '无'
OUTBOUND_DIRECTION_TYPED = '内到外'      # 口述那个写法：表里**没有**这个值

# 行序与取值刻意安排过，一份 fixture 覆盖五件事：
