# ---------------------------------------------------------------------------
# 核心业务系统（D3/D4/D5 系统名 + D7/D8/D9 风险总数）的 fixture
# ---------------------------------------------------------------------------
#
# 表头同样必须是**真实列名**（与 stats/metrics/*.js 里那些常量同一个来源）：
