#   · 财务：内网 1（10.0.0.3）+ 互联网 1（10.0.0.2）-> 2
#   · 运维：内网 0 + 互联网 2（10.0.0.5 两行，一行处置完成、一行待处置）-> 2
# 互联网那几行见 CORE_WEAKPWD_INTERNET_TABLE。
CORE_SYSTEM_BREAKDOWN = [(2, 2, 1), (2, 2, 2), (0, 2, 1)]
CORE_SYSTEM_RISK_TOTALS = [sum(parts) for parts in CORE_SYSTEM_BREAKDOWN]

# C18/D18/E18「核心系统 1/2/3 已闭环风险总数」（用户口径 2026-10-22）：
# 同一批系统名（D3/D4/D5）、同一把「资产表 -> IP」的钥匙，但加式换成 D13 那四段
# （D14 + D15 + D16 + D17），每一项只数 IP 落在该系统集合里的行。
# 这份 fixture 上 D14 段恒为 0（plan core 不喂内网漏洞表切片；D14 的 IP 圈定
# 另有一条带 innerPath 的 fixture 去钉）。
#   · OA（{10.0.0.1, .2}）：D15 = v2 + v11 + v3(.2) = 3，D16 = 弱密码 .1 + 互联网 .2 = 2，
#     D17 = v3(.2 热点漏洞) = 1 -> **6**
#   · 财务（{.2, .3}）：D15 = v4 + v3(.2) = 2，D16 = 互联网 .2 = 1，D17 = v3 + v4 = 2 -> **5**
#   · 运维（{.5}）：D15 = v6 = 1，D16 = 弱密码 .5 + 事件 e4(.5,弱口令,处置完成) = 2，
#     D17 = 0 -> **3**
#   ⚠️ 2026-10-26 D15 从「整格精确等于」改成**包含**，v3（处置完成（误报））、
#   v7/v8 都算进 D15；其中只有 v3 的 IP（.2）落在系统名下，所以 OA / 财务各 +1。
# 三个数刻意互不相等（6 / 5 / 3）：把两个系统的 IP 集合换个个儿、或把 C18 写成
# D18/E18 的别名，这里立刻露红。它们与 D7:D9（5 / 6 / 3）也不是同一组数 ——
# 那一组是「漏洞 + 弱密码 + 事件」三套判据，本组是 D13 的已闭环四段，别混。
CORE_CLOSED_RISK_TOTALS = [6, 5, 3]

# 这 8 格的地址：D3/D4/D5 名字、D6 合计、D7/D8/D9 各系统的风险总数、
# G12 核心系统风险总数（= D7 + D8 + D9，与 D6 同值、同一条加式）
CORE_SYSTEM_CELLS = ['D3', 'D4', 'D5', 'D6', 'D7', 'D8', 'D9', 'G12']

# 只在风险总数那几格里挑：D3/D4/D5 名字那 3 格不依赖总表、永远在写，所以凡是断言
