# 两个集合要是永远相同，把 D11 误实现成「某系统的风险数」也照样能过。
CORE_ASSET_TABLE = [
    ['IP地址', '互联网暴露', '所属业务', '重要级别', '资产名称', '资产类型(一级)', '托管状态'],
    ['10.0.0.1', '暴露', 'OA系统1', '核心', 'a', '服务器', '基础托管'],            # 子串命中：传「OA系统」要认这个；核心资产
    ['10.0.0.2', '未暴露', '财务系统, OA系统', '重要', 'b', '终端', '深度托管'],    # 多段业务名，两个系统都命中；**不是**核心资产
    ['10.0.0.3', '未暴露', '财务系统', '核心', 'c', '服务器', '基础托管'],          # 核心资产；也是 K79/K80 唯一命中行
    ['10.0.0.4', '未知', '', '核心', 'd', '终端', '-'],                     # 核心资产，但不属于任何核心业务系统
    ['10.0.0.5', '未知', '运维系统', '普通', 'e', '网络设备', ''],          # 不是核心资产
]

# 这份表上 G17 = 2（两行「服务器」）、G18 = 2（两行「终端」）、「网络设备」两格都不算。
# K79 = 1（只有 10.0.0.3 是「未暴露」+「服务器」）、K80 = 1（它的「托管状态」是「基础托管」）
# —— 两列必须带上：缺列时 K79/K80 会进 errors，而不是安静地数出 0。
