# ---------------------------------------------------------------------------
# 与 JS 侧桥接
# ---------------------------------------------------------------------------

def call_bridge(bridge, *args):
    """跑一次 scripts/verify_write_layer.js 的子命令，返回它 stdout 的 JSON。"""
    proc = subprocess.run(
        ['node', str(bridge), *args],
        capture_output=True, text=True, encoding='utf-8',
    )
    if proc.returncode != 0:
        raise RuntimeError(f'node {args[0] if args else ""} 失败: {proc.stderr.strip()}')
    return json.loads(proc.stdout.strip())


def run_preprocess(bridge, asset_path, event_path):
    """跑一次「事件表预处理」（下载之后、解析之前那一步），返回它的汇总。

    用户口径 2026-10-12：取值层必须在预处理之后。所以凡是要验「有事件表时 G7 / 时长列
    怎么样」的段，都必须**先跑这一步、再解析**，否则验的是一个生产里不存在的顺序
    （没预处理的事件表上压根没有「遏制时长」列，G7 会报缺列）。

    ⚠️ **event_path 会被原地改写**（追加「内网外网资产」+ 五个时长列）。所以每段用
    自己的 fixture 文件，不要跨段复用同一个文件、也不要把公共 fixtures 传进来。

    :param asset_path: 资产表 fixture（只读，不改）；None = 这次没有资产表
    :param event_path: 事件表 fixture（**原地改写**）
    :returns: 阶段汇总 {ran, asset, event, duration, logs}（形状与 build 返回的 preprocess 一致）
    """
    return call_bridge(bridge, 'preprocess', _b64(json.dumps({
        'assetPath': asset_path,
        'eventPath': event_path,
    })))


# ---------------------------------------------------------------------------
# 逐格比对：模板 vs 落盘结果
# ---------------------------------------------------------------------------

def value_map(path, sheet_name):
    """addr -> (类型, 值, 数字格式, 公式缓存值)，只收「有值」的格子。

    只比「有值」的格子：openpyxl 落盘时会丢掉没有值的空壳单元格，所以拿整份快照
    对比必然不等 —— 那是 openpyxl 的既有行为（旧版 SheetJS 同样如此），与取值层无关。
    这里比的是「值有没有被改动」，空壳消失不计。

    缓存值必须另读一遍 data_only=True：data_only=False 读公式格拿到的是公式串
    （`=TODAY()`），前后一模一样，看不出缓存的丢失。
    """
    wb = load_workbook(path, data_only=False)
    wb_cached = load_workbook(path, data_only=True)
    ws, ws_cached = wb[sheet_name], wb_cached[sheet_name]

    out = {}
    for row in ws.iter_rows():
        for cell in row:
            if cell.value is None or cell.value == '':
                continue
            cached = ws_cached[cell.coordinate].value
            out[cell.coordinate] = (cell.data_type, cell.value, cell.number_format, cached)
    return out


def sorted_union(*groups):
    """几个 EXPECTED_* 分组的并集（排序后）。

    这些分组是按**原因**分的，彼此会重叠（D6:D9 既是「核心业务系统」那 7 格的一部分，
    也在「没传系统 -> 写 0」那一堆里）。凡是把两组相加去清点"这次跑了哪些格"的地方，
    一律走这里 —— 直接 `+` 会把同一格数两遍，与落盘结果比对必红。
    """
    out = set()
    for group in groups:
        out.update(group)
    return sorted(out)


def changed_addrs(before, after):
    """两份 value_map 的差异，返回已排序的地址数组。"""
    changed = [k for k, v in after.items() if before.get(k) != v]
    changed += [k for k in before if k not in after]
    return sorted(changed)


def render(entry):
    """把 value_map 的一条记录压成一行，方便打错误信息。"""
    if entry is None:
        return '(无)'
    kind, value, fmt, cached = entry
    text = json.dumps(value, ensure_ascii=False, default=str)
    if fmt and fmt != 'General':
        text += f' [z={fmt}]'
    if kind == 'f' and cached is not None:
        text += f' [缓存={json.dumps(cached, ensure_ascii=False, default=str)}]'
    return text


class Checker:
    """攒断言，最后统一报告有几条没过 —— 不要在第一条就中断，那样看不到后面的问题。"""

    def __init__(self):
        self.failures = []

    def check(self, ok, label, actual, expected=None):
        mark = '✓' if ok else '✗'
        suffix = '' if expected is None else f'  (期望 {expected})'
        print(f'  {mark} {label}: {actual}{suffix}')
        if not ok:
            self.failures.append(label)

    def note(self, label, actual):
        print(f'  · {label}: {actual}')

    def section(self, title):
        print(f'\n【{title}】')


# ---------------------------------------------------------------------------
# fixture：三份平台导出表的替身
# ---------------------------------------------------------------------------

def write_sheet(path, aoa):
    wb = Workbook()
    ws = wb.active
    for row in aoa:
        ws.append(row)
    wb.save(path)
    return str(path)


def write_book(path, sheets):
    """{sheet 名: aoa} -> 一个**多-sheet**工作簿，返回路径。

    漏洞表 2026-10-16 起一个下载件里是两张 sheet（「内网漏洞表」「互联网漏洞表」，
    见 build_report.py 的 TABLE_SHEET_NAMES['vuln']），单-sheet 的 write_sheet
    喂不动它 —— 搬表那层按**名字**取 sheet，名字对不上会直接抛。
    sheet 顺序即 dict 的插入顺序（内网在前，与生产一致）。
    """
    wb = Workbook()
    first = True
    for name, aoa in sheets.items():
        ws = wb.active if first else wb.create_sheet()
        first = False
        ws.title = name
        for row in aoa:
            ws.append(row)
    wb.save(path)
    return str(path)


